TLM.f("Sancti/06-19o",{"officium":"SS. Gervasii et Protasii Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 84:9"},{"k":"text","la":"Loquétur Dóminus pacem in plebem suam: et super sanctos suos, et in eos, qui convertúntur ad ipsum."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam, avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquétur Dóminus pacem in plebem suam: et super sanctos suos, et in eos, qui convertúntur ad ipsum."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua sanctórum Mártyrum tuorum Gervásii et Protásii sollemnitáte lætíficas: concéde propítius; ut, quorum gaudémus méritis, accendámur exémplis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 4:13-19"},{"k":"text","la":"Caríssimi: Communicántes Christi passiónibus gaudéte, ut et in revelatióne glóriæ ejus gaudeátis exsultántes. Si exprobrámini in nómine Christi, beáti éritis: quóniam quod est honóris, glóriæ et virtútis Dei, et qui est ejus Spíritus, super vos requiéscit. Nemo autem vestrum patiátur ut homicída, aut fur, aut malédicus, aut alienórum appetítor. Si autem ut christiánus, non erubéscat: gloríficet autem Deum in isto nomine. Quóniam tempus est, ut incípiat judícium a domo Dei. Si autem primum a nobis: quis finis eórum, qui non credunt Dei Evangélio? Et si justus vix salvábitur, ímpius et peccátor ubi parébunt? Itaque et hi, qui patiúntur secúndum voluntátem Dei, fideli Creatóri comméndent ánimas suas in benefáctis."}],"Graduale":[{"k":"ref","la":"Exodi 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 16:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Oblátis, quaésumus, Dómine, placáre munéribus: et, intercedéntibus sanctis Martýribus tuis, a cunctis nos defénde perículis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 78:2; 78:11"},{"k":"text","la":"Posuérunt mortália servórum tuórum, Dómine, escas volatílibus cœli, carnes Sanctórum tuórum béstiis terræ: secúndum magnitúdinem bráchii tui pósside fílios morte punitórum."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedéntibus sanctis Martýribus tuis Gervásii et Protásii, coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1902189fefe92bdf":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom svojih svetih mučenika Gervazija i Protazija, daj milostivo da nas oduševe primjeri onih kojih se zaslugama radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"9d18bbbbeefb7c8d":{"t":"Ublaži se, molimo, Gospodine, prikaznim darovima i po zagovoru tvojih svetih mučenika brani nas od svih pogibelji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0de7d6b17cd069aa":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, ova Pričest očisti od opačina i po zagovoru svetih tvojih mučenika Gervazija i Protazija, učini dionicima nebeske pomoći.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
